#### Phase 3: Shared Dependencies (Week 3)

1. **Module Federation Shared Config**

   ```typescript
   // vite.config.ts (Shell application)
   import { defineConfig } from 'vite';
   import federation from '@originjs/vite-plugin-federation';

   export default defineConfig({
     plugins: [
       react(),
       federation({
         name: 'shell',
         filename: 'remoteEntry.js',
         exposes: {
           './react': 'react',
           './react-dom': 'react-dom',
           './design-system': '@gainwell/design-system'
         },
         shared: {
           react: { singleton: true, requiredVersion: '^18.0.0' },
           'react-dom': { singleton: true, requiredVersion: '^18.0.0' },
           '@gainwell/design-system': { singleton: true }
         }
       })
     ]
   });
   ```

2. **Module Imports Shared Dependencies**

   ```typescript
   // vite.config.ts (Claims module)
   import federation from '@originjs/vite-plugin-federation';

   export default defineConfig({
     plugins: [
       react(),
       federation({
         name: 'claims_module',
         filename: 'remoteEntry.js',
         exposes: {
           './ClaimsApp': './src/ClaimsApp'
         },
         remotes: {
           shell: 'http://localhost:3000/assets/remoteEntry.js'
         },
         shared: {
           react: { singleton: true, requiredVersion: '^18.0.0' },
           'react-dom': { singleton: true, requiredVersion: '^18.0.0' },
           '@gainwell/design-system': { singleton: true }
         }
       })
     ]
   });
   ```

