#### Example 1: Performance Budget (Lighthouse CI)

```javascript
// lighthouserc.js - Enforce performance budgets
module.exports = {
  ci: {
    collect: {
      url: [
        'http://localhost:3000/claims',
        'http://localhost:3000/members',
        'http://localhost:3000/providers'
      ],
      startServerCommand: 'npm run preview',
      numberOfRuns: 3
    },
    assert: {
      preset: 'lighthouse:recommended',
      assertions: {
        // Core Web Vitals thresholds
        'categories:performance': ['error', { minScore: 0.9 }],
        'largest-contentful-paint': ['error', { maxNumericValue: 2500 }],
        'first-input-delay': ['error', { maxNumericValue: 100 }],
        'cumulative-layout-shift': ['error', { maxNumericValue: 0.1 }],
        'total-blocking-time': ['error', { maxNumericValue: 300 }],

        // Resource budgets
        'resource-summary:script:size': ['error', { maxNumericValue: 500000 }], // 500KB JS max
        'resource-summary:image:size': ['error', { maxNumericValue: 500000 }],  // 500KB images max
        'resource-summary:stylesheet:size': ['error', { maxNumericValue: 50000 }] // 50KB CSS max
      }
    },
    upload: {
      target: 'temporary-public-storage'
    }
  }
};
```

