[patterns/application/micro-frontend/PTN-APP-MFE-014-performance-optimization-pattern.md#example-3-vite-performance-configuration]

#### Example 3: Vite Performance Configuration

```typescript
// vite.config.ts - Vite production optimizations
import { defineConfig } from 'vite';
import react from '@vitejs/plugin-react';
import { visualizer } from 'rollup-plugin-visualizer';
import viteCompression from 'vite-plugin-compression';

export default defineConfig({
  plugins: [
    react(),
    // Bundle visualization
    visualizer({
      open: process.env.ANALYZE === 'true',
      gzipSize: true,
      brotliSize: true,
      filename: 'dist/bundle-analysis.html'
    }),
    // Brotli and Gzip compression
    viteCompression({
      algorithm: 'brotliCompress',
      ext: '.br'
    }),
    viteCompression({
      algorithm: 'gzip',
      ext: '.gz'
    })
  ],
  build: {
    target: 'es2015',
    minify: 'esbuild',
    rollupOptions: {
      output: {
        // Code splitting strategy
        manualChunks: {
          'react-vendor': ['react', 'react-dom', 'react-router-dom'],
          'design-system': ['@gainwell/design-system'],
          'charting': ['recharts', 'd3'] // Heavy charting libraries separate
        },
        // Content-hashed filenames
        entryFileNames: 'assets/[name].[hash].js',
        chunkFileNames: 'assets/[name].[hash].js',
        assetFileNames: 'assets/[name].[hash].[ext]'
      }
    },
    // Source maps for production debugging (but not inline)
    sourcemap: true,
    // Warn if bundle > 500KB
    chunkSizeWarningLimit: 500
  }
});
```
